import{_ as n,C as s,o,c as r,j as e,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse('{"title":"Watch a Playwright run","description":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window.","frontmatter":{"title":"Watch a Playwright run","description":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/watch-a-run.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/watch-a-run.html"}],["meta",{"property":"og:title","content":"Watch a Playwright run | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window."}]]},"headers":[],"relativePath":"features/watch-a-run.md","filePath":"features/watch-a-run.md","lastUpdated":1794573673000}'),l={name:"features/watch-a-run.md"};function p(u,t,w,c,g,m){const a=s("Needs");return o(),r("div",null,[t[0]||(t[0]=e("h1",{id:"watch-a-run",tabindex:"-1"},[i("Watch a run "),e("a",{class:"header-anchor",href:"#watch-a-run","aria-label":'Permalink to "Watch a run"'},"​")],-1)),h(a,{reporter:""}),t[1]||(t[1]=d('<p>A run that reports to a Piwi instance has one number there, <code>#78</code>, and one page. Every tool that shows the run while it goes names it by that number, links that page, and says how far the run is and where a test stopped in the same words, so a run started in VS Code reads the same in the terminal, in Piwi Picker&#39;s Runs window and on the dashboard.</p><h2 id="the-run-s-number-and-page" tabindex="-1">The run&#39;s number and page <a class="header-anchor" href="#the-run-s-number-and-page" aria-label="Permalink to &quot;The run&#39;s number and page&quot;">​</a></h2><p>The reporter learns the run&#39;s number as the run starts: from the global setup that registered it, else as its stream to the instance opens. It prints the page once, and tells it to the editor or the desktop app that follows the run. The page is under the instance&#39;s public address when the instance sets <code>PIWI_SITE_URL</code>, else under the address the reporter reached it at. A tool links it only on this machine or under an instance it connects to itself: in an editor, the instance of a Playwright config of the window; in the desktop app, the team instance whose run requests it takes. A page elsewhere, which the test&#39;s own code could name, is not shown, and the run reads as one with no number.</p><table tabindex="0"><thead><tr><th>Where</th><th>What it shows</th></tr></thead><tbody><tr><td>The terminal</td><td><code>[Piwi Dashboard] View live progress: https://piwi.example.com/test-runs/78</code>, once, as the run starts</td></tr><tr><td>VS Code</td><td>The run-control item: <code>#78 · 3 of 9</code>, its tooltip <strong>Open run #78</strong>; the status bar item, while your run goes: <strong>Open run #78 (running)</strong> first in its tooltip; <strong>Piwi: Open the run page</strong> and <strong>Piwi: Open the run in progress</strong> in the Command Palette</td></tr><tr><td>JetBrains IDEs</td><td>The status bar item: <code>Piwi: run #78 · 3 of 9</code>, kept beside a stop or a share; <strong>Open Run #78</strong> in its menu; <strong>Open Run #78 (Running)</strong> in place of <strong>Open the Latest Run in the Dashboard</strong> while it goes</td></tr><tr><td>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></td><td><strong>Run #78</strong>, <strong>Open</strong> and <strong>Copy link</strong> on the run&#39;s card, while it runs and after it ended, with its progress and how it ended</td></tr><tr><td>The desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a></td><td><strong>Run #78 · Open</strong> under each run of its hub, a run a team instance asked for included, whose page opens in the browser; <strong>Open run #78</strong> on a run the app&#39;s own server holds</td></tr><tr><td><strong>Debug in my editor</strong></td><td>Once the editor runs the test: &quot;Following run #81 in VS Code · Open&quot; beside the button</td></tr></tbody></table><p>A run that reports to no instance, or that runs with <code>streaming: false</code> and no global setup, has no number until its results are sent, and the tools show it without one.</p><h2 id="how-far-it-is" tabindex="-1">How far it is <a class="header-anchor" href="#how-far-it-is" aria-label="Permalink to &quot;How far it is&quot;">​</a></h2><p>The reporter&#39;s own process tells the editor or the desktop app how many tests the run holds, how many ended and how, and how the run ended with its first failure. The editors&#39; status bars and the Runs window count it the same way: each test once, by its last attempt. The desktop tray counts the lines of the run&#39;s output instead, a retry again.</p><p>On the dashboard, Home&#39;s <strong>Recent activity</strong>, a project&#39;s runs list and the <strong>Projects</strong> page show a running run with the count bar and how many results are in: <code>120 of 400 · 2 failed</code>. Its row moves on by itself as results reach the instance, at most every 2 seconds, without the page reading the list again. Until the run ends these count each result as the reporter sends it, a retry again; the run&#39;s page counts each test once.</p><p>The status bar item&#39;s tooltip also says what each worker runs now (<code>Worker 2 · cart › adds a mug · stopped</code>). In VS Code, the Testing view&#39;s test run of your run writes in its output each test a worker starts, each stop and why, with the line it stands at, and each stop answered.</p><p>In VS Code, a run in progress that is not yours, a CI run or a teammate&#39;s on your branch or on the branch your results are compared with, names itself so: the status bar says <code>CI run #125</code> or <code>run #126</code>, and the Testing view shows it as <code>Piwi: CI run #125 on main</code>, its tests&#39; results as they end, never as your tests running. Your own run stays in the status bar whichever Playwright config the active file belongs to.</p><h2 id="where-a-test-stopped" tabindex="-1">Where a test stopped <a class="header-anchor" href="#where-a-test-stopped" aria-label="Permalink to &quot;Where a test stopped&quot;">​</a></h2><p>A test of a run on your machine stops at a breakpoint, after a step, at a Pause, at the line it was run to, or at <code>page.pause()</code>. Every tool says why in the same words:</p><ul><li><strong>Stopped at a breakpoint</strong></li><li><strong>Stopped after a step</strong></li><li><strong>Paused</strong></li><li><strong>Stopped at the line it ran to</strong></li><li><strong>Stopped at page.pause()</strong></li><li><strong>Stopped</strong>, for a reason a newer reporter names</li></ul><p>A stop an agent asked for reads <strong>Paused by the agent</strong> in the editors. A failure held for a look says how the test failed instead. The run page shows the stop on the test&#39;s row (<a href="./share-live.html#stops-shared-or-not">stops, shared or not</a>), the editors above the stopped line, the Runs window on the worker, and the terminal on a line of its own:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[piwi] Stopped at a breakpoint at tests/cart.spec.ts:12 before Click: Resume, Step or Finish in Visual Studio Code.</span></span></code></pre></div><p>The line names the editor that steers the run, or the desktop app. After you edit the file at a stop, the Runs window names the stopped line where it stands now, as the editor does.</p><p>At a stop of a headed run, every tool offers <strong>Show the browser</strong>, which brings the test&#39;s window to the front, as far as your system lets a window come forward: <strong>Piwi: Show the stopped test&#39;s browser</strong> in VS Code and the stop&#39;s hover, <strong>Tools → Piwi → Show the Stopped Test&#39;s Browser</strong> in a JetBrains IDE, and a button in the Runs window and the desktop app&#39;s tray. A headless run has no window to show, and an older reporter offers none: update it.</p><h2 id="share-with-playwright-tools" tabindex="-1">Share with Playwright tools <a class="header-anchor" href="#share-with-playwright-tools" aria-label="Permalink to &quot;Share with Playwright tools&quot;">​</a></h2><p>At a stop, <strong>Share with Playwright tools</strong> (the stop&#39;s hover and <strong>Piwi: Share the stopped test&#39;s browser with Playwright tools</strong> in VS Code; the stop&#39;s menu and <strong>Tools → Piwi</strong> in a JetBrains IDE) binds the test&#39;s browser for Playwright&#39;s own tools, so <code>npx playwright cli attach piwi-&lt;run&gt;-w&lt;worker&gt;</code> and Playwright&#39;s dashboard can join it. It is off until you ask, every time, and asks first: a shared browser is open to any process of yours, which can read its pages and run code in them. It is shared until the test ends, and no agent can share it.</p><h2 id="the-terminal-s-lines" tabindex="-1">The terminal&#39;s lines <a class="header-anchor" href="#the-terminal-s-lines" aria-label="Permalink to &quot;The terminal&#39;s lines&quot;">​</a></h2><p>A run prints one line for its page, and one when it follows an editor or the desktop app (<a href="./terminal-runs.html">runs started outside Piwi</a>). A run whose output goes to a file or a pipe follows it unattended and says so:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Following this run in Visual Studio Code (pid 41230), unattended: its output goes to no terminal, so no failure waits and only a Pause stops it. PIWI_EDITOR=on attends it, PIWI_EDITOR=off runs it alone.</span></span></code></pre></div><p>The other lines of a run&#39;s start (its project and Playwright version, its shard, the stream opening on time) are printed with <code>PIWI_VERBOSE=true</code> alone. A stream that opens late, a failure link and a warning are always printed.</p><p>In a terminal outside CI, the run&#39;s page is a link. Windows Terminal and ConEmu show how far the run is in the tab and the taskbar, and Ghostty 1.2 or later atop the terminal, red once a test failed. <code>PIWI_TERMINAL_PROGRESS=off</code> turns both off, and <code>PIWI_TERMINAL_PROGRESS=on</code> sends the progress to any terminal: one that reads it as a notification shows one at each step.</p><h2 id="when-the-run-does-not-reach-the-instance" tabindex="-1">When the run does not reach the instance <a class="header-anchor" href="#when-the-run-does-not-reach-the-instance" aria-label="Permalink to &quot;When the run does not reach the instance&quot;">​</a></h2><p>When a run the editor started ends without reaching the instance, the editor says which of two things happened: its reporter ran but sent nothing (its lines in the run&#39;s output say why: the server address, the key, or an instance that refused it), or the Playwright config has no Piwi reporter.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: watch a running test&#39;s page from its run page</li><li><a href="./share-live.html">Share a run live</a>: let a teammate watch a run on your machine</li><li><a href="./runs-window.html">Runs window</a>: follow and steer the editor&#39;s runs from Piwi Picker</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls at a stop</li><li><a href="/guide/concepts.html#run-number">Concepts</a>: the words used here</li></ul>',28))])}const y=n(l,[["render",p]]);export{b as __pageData,y as default};
